import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    stack = []
    for num in a:
        if stack and stack[-1] == num:
            stack[-1] += 1
        else:
            stack.append(num)

    print(len(stack))
    print(' '.join(map(str, stack)))

if __name__ == "__main__":
    main()
